    background: url('https://www.pinterest.com/pin/56013589124573302/') center no-repeat !important;
    background-size: cover !important; /* Adjusts the image size to fill the screen */
    color: #ff69b4 !important; /* Hello Kitty pink */
  }

  /* Headers */
  .header-2iDDac {
    background-color: rgba(0, 0, 0, 0.7) !important; /* Semi-transparent for background visibility */
    color: #ffffff !important; /* White text for contrast */
  }

  /* Buttons */
  .button-1cXPpT {
    background-color: #ffb6c1 !important; /* Light pink */
    border: 2px solid #ff69b4 !important;
    color: #1a1a1a !important; /* Dark text for contrast */
  }

  /* Text fields */
  .textArea-2CLwUE {
    background-color: rgba(50, 50, 50, 0.8) !important;
